import re, glob, os

# Collect all cited keys from .tex files
cited = set()
# Only check active files (included by main.tex)
for f in glob.glob('*.tex'):
    with open(f) as fh:
        content = fh.read()
    # Match \cite{...}, \citep{...}, \citet{...}
    for m in re.finditer(r'\\cite[ptau]*\{([^}]+)\}', content):
        for key in m.group(1).split(','):
            cited.add(key.strip())

# Collect all bib keys
bib_keys = {}
for f in glob.glob('*.bib'):
    with open(f) as fh:
        content = fh.read()
    for m in re.finditer(r'@\w+\{([^,\s]+)', content):
        key = m.group(1)
        if key not in bib_keys:
            bib_keys[key] = f
        else:
            bib_keys[key] = bib_keys[key] + ', ' + f

orphans = set(bib_keys.keys()) - cited
missing = cited - set(bib_keys.keys())

print(f'Total bib entries: {len(bib_keys)}')
print(f'Total cited keys: {len(cited)}')
print(f'\nOrphan bib entries ({len(orphans)}):')
for k in sorted(orphans):
    print(f'  {k}  [{bib_keys[k]}]')
print(f'\nMissing bib entries ({len(missing)}):')
for k in sorted(missing):
    print(f'  {k}')
